import 'package:flutter/material.dart';import 'package:flutter_riverpod/flutter_riverpod.dart';import 'package:url_launcher/url_launcher.dart';import '../../../core/providers/app_providers.dart';import '../../../core/domain/extended_entities.dart';
class EmergencyScreen extends ConsumerStatefulWidget{const EmergencyScreen({super.key});@override ConsumerState<EmergencyScreen> createState()=>_EmergencyScreenState();}
class _EmergencyScreenState extends ConsumerState<EmergencyScreen>{final name=TextEditingController(),phone=TextEditingController(),address=TextEditingController(),hours=TextEditingController();String type='Veterinarian';@override void dispose(){name.dispose();phone.dispose();address.dispose();hours.dispose();super.dispose();}
Future<void> add()async{if(name.text.trim().isEmpty)return;final p=ref.read(appControllerProvider).selectedPet;final e=ContactCard(id:DateTime.now().microsecondsSinceEpoch.toString(),type:type,name:name.text.trim(),petId:p?.id,phone:phone.text.trim(),address:address.text.trim(),hours:hours.text.trim(),isEmergency:type=='Emergency clinic');await ref.read(appControllerProvider).save('contacts',e.toMap());name.clear();phone.clear();address.clear();hours.clear();}
@override Widget build(BuildContext context){final c=ref.watch(appControllerProvider),pet=c.selectedPet;final contacts=c.items('contacts').map(ContactCard.fromMap).where((e)=>e.petId==null||e.petId==pet?.id).toList();return Scaffold(appBar:AppBar(title:const Text('Vet & emergency contacts')),body:ListView(padding:const EdgeInsets.all(16),children:[const Text('Add the contact details you may need offline. Verify phone numbers and service availability directly.'),const SizedBox(height:12),DropdownButtonFormField<String>(value:type,decoration:const InputDecoration(labelText:'Contact type'),items:['Veterinarian','Emergency clinic','Caregiver'].map((v)=>DropdownMenuItem(value:v,child:Text(v))).toList(),onChanged:(v)=>setState(()=>type=v!)),const SizedBox(height:8),TextField(controller:name,decoration:const InputDecoration(labelText:'Clinic / contact name')),const SizedBox(height:8),TextField(controller:phone,keyboardType:TextInputType.phone,decoration:const InputDecoration(labelText:'Phone')),const SizedBox(height:8),TextField(controller:address,decoration:const InputDecoration(labelText:'Address')),const SizedBox(height:8),TextField(controller:hours,decoration:const InputDecoration(labelText:'Opening hours note')),const SizedBox(height:10),FilledButton(onPressed:add,child:const Text('Save contact')),const SizedBox(height:20),...contacts.map((e)=>Card(child:ListTile(title:Text(e.name),subtitle:Text('${e.type} · ${e.phone}\n${e.address}\n${e.hours}'),trailing:IconButton(icon:const Icon(Icons.call),onPressed:e.phone.isEmpty?null:()=>launchUrl(Uri(scheme:'tel',path:e.phone)))))) ,const SizedBox(height:12),const Text('Emergency guidance: contact a veterinarian or local emergency veterinary clinic immediately. PawPal does not diagnose or triage. Verify all emergency-resource numbers before relying on them.') ]));}}
